import{_ as a,o,c as s,a5 as i}from"./chunks/framework.BwlBv862.js";const m=JSON.parse('{"title":"Configure sons e fala","description":"","frontmatter":{"title":"Configure sons e fala","docId":"user.plugins.audio","translationKey":"user.plugins.audio","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"b6be887705d13dfe120f3e07dc4006ec0efa1472b6dbe0ccfc1ebfc1e83f3672","translationRevision":"b196270cac210dccdc681480f77202d894cc91e5d9875af7c5d3a6bea36fe20e","order":20},"headers":[],"relativePath":"pt/user/plugins/audio.md","filePath":"pt/user/plugins/audio.md","lastUpdated":1794611623000}'),t={name:"pt/user/plugins/audio.md"};function r(d,e,n,u,c,l){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="set-up-sounds-and-speech" tabindex="-1">Configure sons e fala <a class="header-anchor" href="#set-up-sounds-and-speech" aria-label="Permalink to &quot;Configure sons e fala {#set-up-sounds-and-speech}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Reproduza um som previsível antes de conectar áudio a uma LIVE movimentada. Você precisa de um dispositivo de saída funcional e de um arquivo de áudio existente e compatível. A ação local <strong>Play a sound</strong> (<code>audio.play</code>) é integrada; provedores de fala, como uma integração SonicBoom instalada, exigem sua própria configuração de plugin/serviço.</p><h2 id="test-a-local-sound" tabindex="-1">Teste um som local <a class="header-anchor" href="#test-a-local-sound" aria-label="Permalink to &quot;Teste um som local {#test-a-local-sound}&quot;">​</a></h2><ol><li>Em <strong>Automations → Actions</strong>, crie <strong>Play a sound</strong> (<code>audio.play</code>). Selecione um arquivo existente com o seletor de mídia.</li><li>Defina o volume como <code>0.2</code> para a primeira verificação. O intervalo aceito é de <code>0</code> a <code>1</code>; zero é silêncio.</li><li>Escolha a política de sobreposição: <code>allow</code> permite reprodução simultânea, <code>restart</code> reinicia o som e <code>drop</code> ignora uma nova instância enquanto ele já toca.</li><li>Salve a ação e leia a configuração antes de selecionar <strong>Test</strong>. Esse teste pode reproduzir som audível.</li><li>Ouça pelo dispositivo desejado. Após a reprodução local funcionar, vincule a ação a um evento com <a href="./../automations/recipes.html">filtro e intervalo de espera</a> conservadores.</li></ol><p>A ação mantém uma referência de mídia baseada em caminho. O TikTools não copia o arquivo de áudio para o banco de dados. Mantenha o arquivo nesse caminho e inclua-o separadamente ao mover ou fazer backup da configuração.</p><h2 id="configure-optional-speech" tabindex="-1">Configure fala opcional <a class="header-anchor" href="#configure-optional-speech" aria-label="Permalink to &quot;Configure fala opcional {#configure-optional-speech}&quot;">​</a></h2><p>Instale o plugin de fala confiável por <a href="./">Plugins</a>. Nos controles de conexão/configurações, verifique endereço do serviço, autenticação e provedor, idioma e voz/perfil selecionados. Carregue um catálogo de vozes antes de testar uma frase curta não sensível. Uma voz ausente deve ser investigada como incompatibilidade de catálogo, propriedade ou provedor, em vez de substituída por um identificador inventado.</p><p>No SonicBoom, síntese, admissão de reprodução e conclusão audível são resultados diferentes. Uma resposta enfileirada ou iniciada não comprova que uma pessoa ouviu a frase. A fala clonada pode ser mais lenta que a chegada de mensagens de chat, portanto inspecione os diagnósticos de fila/saturação e mantenha limitada a admissão de eventos.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Resultado esperado, status e recuperação <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Resultado esperado, status e recuperação {#expected-result-status-and-recovery}&quot;">​</a></h2><p>A reprodução de áudio local está disponível quando o host anuncia suporte a áudio. A fala continua dependente do plugin instalado e do serviço acessível; a aceitação por provedor/dispositivo/plataforma não é garantida aqui. Se não houver som, verifique existência do arquivo, volume, dispositivo de saída, estado de pausa e erro da execução. Se a fala falhar, confira o serviço e o catálogo de vozes antes de tentar novamente. Evite testes repetidos de efeitos durante uma transmissão e use <a href="./../preferences/troubleshooting.html">diagnósticos</a> sem compartilhar tokens ou texto privado falado.</p>',11)])])}const f=a(t,[["render",r]]);export{m as __pageData,f as default};
